  if(!LESSONS[id])LESSONS[id]={title:C[id][0]+' (runs here)',lessons:[]};
  if(id==='sql')LESSONS[id].lessons.push({t,body:'<p>'+b+'</p>',sql:x,q:{q,o:[r,w1,w2],a:0}});
  else if(id==='python')LESSONS[id].lessons.push({t,body:'<p>'+b+'</p>',py:x,q:{q,o:[r,w1,w2],a:0}});
  else LESSONS[id].lessons.push({t,body:'<p>'+b+'</p>',sample:x,q:{q,o:[r,w1,w2],a:0}});
