 Object.keys(C).forEach(id=>{
  const [N,focus,cm,fam]=C[id];
  if(!LESSONS[id])LESSONS[id]={title:N+' (runs here)',lessons:[]};
  const L=LESSONS[id].lessons;
  for(let i=L.length;i<40;i++){
   const [title,desc,q,right,w1,w2]=B[i],f=FACET[i];
   let stem=q.split('{N}').join(N),opts=[right,w1,w2];
   if(f&&fam){
    const pool=[];Object.keys(C).forEach(k=>{if(C[k][3]&&C[k][3]!==fam&&C[k][f[0]]&&!pool.includes(C[k][f[0]])&&C[k][f[0]]!==C[id][f[0]])pool.push(C[k][f[0]])});
    const a=hash(id+i)%pool.length;
    stem=f[1].split('{N}').join(N);opts=[C[id][f[0]],pool[a],pool[(a+1+hash(id)%(pool.length-1))%pool.length]];
    if(opts[1]===opts[2])opts[2]=pool[(a+2)%pool.length];
   }
   const m=place(opts,0,id+':'+i);
   L.push({t:`${String(i+1).padStart(2,'0')}. ${title}`,body:makeBody(N,title,desc,focus),sample:`${cm} ${N}: ${title}\n${cm} Goal: ${desc}\n${cm} Working on: ${focus}\n${cm} 1. Describe the expected result.\n${cm} 2. Try a normal input and a boundary input.\n${cm} 3. Record the result and explain any difference.`,q:{q:stem,o:m.o,a:m.a}});
  }
 });
